#include <stdio.h>

// Function to compute greatest common divisor
long long gcd(long long a, long long b) {
    while (b != 0) {
        long long temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// Function to compute least common multiple
long long lcm(long long a, long long b) {
    return a / gcd(a, b) * b;
}

int main() {
    int n;
    scanf("%d", &n);

    long long d[100], v[100];
    for (int i = 0; i < n; i++) {
        scanf("%lld %lld", &d[i], &v[i]);
    }

    // Compute time for each student to complete one lap: time = distance / speed
    // We work with fractions: time_i = d_i / v_i
    // We need LCM of these times.
    // Represent times as fractions in lowest terms: numerator = d_i / g, denominator = v_i / g
    // where g = gcd(d_i, v_i)

    long long num[100], den[100];
    for (int i = 0; i < n; i++) {
        long long g = gcd(d[i], v[i]);
        num[i] = d[i] / g;   // numerator of reduced time
        den[i] = v[i] / g;   // denominator of reduced time
    }

    // LCM of fractions: LCM of numerators / GCD of denominators
    long long lcm_num = num[0];
    long long gcd_den = den[0];

    for (int i = 1; i < n; i++) {
        lcm_num = lcm(lcm_num, num[i]);
        gcd_den = gcd(gcd_den, den[i]);
    }

    // The meeting time T = lcm_num / gcd_den (in hours)
    // We need laps for each student: laps_i = T * v_i / d_i
    // = (lcm_num / gcd_den) * v_i / d_i

    // Since we want integer laps, compute:
    // laps_i = (lcm_num * v_i) / (gcd_den * d_i)

    for (int i = 0; i < n; i++) {
        long long laps = (lcm_num * v[i]) / (gcd_den * d[i]);
        printf("%lld\n", laps);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

static ll gcdll(ll a, ll b) {
    while (b != 0) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    ll *d = (ll *)malloc(sizeof(ll) * n);
    ll *v = (ll *)malloc(sizeof(ll) * n);
    ll *num = (ll *)malloc(sizeof(ll) * n);
    ll *den = (ll *)malloc(sizeof(ll) * n);

    for (int i = 0; i < n; i++) {
        scanf("%lld %lld", &d[i], &v[i]);

        ll g = gcdll(d[i], v[i]);
        num[i] = d[i] / g;  // reduced lap time numerator
        den[i] = v[i] / g;  // reduced lap time denominator
    }

    // LCM of all reduced numerators
    ll lcm_num = num[0];
    for (int i = 1; i < n; i++) {
        ll g = gcdll(lcm_num, num[i]);
        lcm_num = (lcm_num / g) * num[i];
    }

    // GCD of all reduced denominators
    ll gcd_den = den[0];
    for (int i = 1; i < n; i++) {
        gcd_den = gcdll(gcd_den, den[i]);
    }

    // Common meeting time T = lcm_num / gcd_den
    // Laps of student i = T / (d_i / v_i) = (lcm_num * den[i]) / (gcd_den * num[i])
    for (int i = 0; i < n; i++) {
        ll laps = (lcm_num / num[i]) * (den[i] / gcd_den);
        if (i) printf(" ");
        printf("%lld", laps);
    }
    printf("\n");

    free(d);
    free(v);
    free(num);
    free(den);
    return 0;
}

