typedef long long ll;

ll gcd(ll a, ll b) { return b == 0 ? a : gcd(b, a%b); }
ll lcm(ll a, ll b) { return a / gcd(a,b) * b; }

int main() {
    int n;
    while (cin >> n && n != 0) {
        vector<ll> d(n), v(n);
        for (int i = 0; i < n; i++) cin >> d[i] >> v[i];

        // fraction for student i: d[i]/v[i], reduce it
        vector<ll> num(n), den(n);
        for (int i = 0; i < n; i++) {
            ll g = gcd(d[i], v[i]);
            num[i] = d[i] / g;
            den[i] = v[i] / g;
        }

        // LCM of fractions = LCM(numerators) / GCD(denominators)
        ll L_num = num[0], G_den = den[0];
        for (int i = 1; i < n; i++) {
            L_num = lcm(L_num, num[i]);
            G_den = gcd(G_den, den[i]);
        }
        // T = L_num / G_den

        // laps[i] = T / (d[i]/v[i]) = T * v[i] / d[i] = (L_num/G_den) * v[i] / d[i]
        // = (L_num * v[i]) / (G_den * d[i])
        for (int i = 0; i < n; i++) {
            ll laps = (L_num * den[i]) / (G_den * num[i]);
            // den[i] = v[i]/g, num[i] = d[i]/g
            // laps = L_num * (v[i]/g) / (G_den * (d[i]/g)) = L_num * v[i] / (G_den * d[i])
            cout << laps;
            if (i < n-1) cout << " ";
        }
        cout << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

long long gcd(long long a, long long b) {
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

long long lcm(long long a, long long b) {
    return a / gcd(a, b) * b;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> d(n), v(n);
    for (int i = 0; i < n; i++) {
        cin >> d[i] >> v[i];
    }

    // We need to find the smallest positive time T such that for each student i,
    // T * v[i] / d[i] is an integer (number of laps completed).
    // Let T = k * (d[i] / v[i]) for some integer k, so T is a common multiple of the lap times.
    // Lap time of student i: t_i = d[i] / v[i] hours.
    // We want T = LCM of all t_i, but t_i are rational numbers.
    // Write t_i as fraction: d[i] / v[i].
    // LCM of fractions = LCM of numerators / GCD of denominators.
    // But careful: we want T such that T / t_i is integer.
    // Equivalent to T * v[i] / d[i] integer.
    // Let T = p/q in reduced form? Better: work with integers.
    // We seek smallest positive T such that for all i: (T * v[i]) % d[i] == 0.
    // T must be a multiple of d[i] / gcd(v[i], d[i])? Actually:
    // T * v[i] % d[i] == 0  <=>  d[i] divides T * v[i].
    // Let g_i = gcd(v[i], d[i]). Then condition: (d[i]/g_i) divides T * (v[i]/g_i).
    // Since v[i]/g_i and d[i]/g_i are coprime, we need (d[i]/g_i) divides T.
    // So T must be a multiple of d[i] / g_i.
    // Thus T must be a multiple of L = lcm of all (d[i] / gcd(v[i], d[i])).
    // Then answer laps = T * v[i] / d[i].

    long long L = 1;
    for (int i = 0; i < n; i++) {
        long long g = gcd(v[i], d[i]);
        long long need = d[i] / g;  // d[i]/g divides T
        L = lcm(L, need);
    }

    for (int i = 0; i < n; i++) {
        long long laps = L * v[i] / d[i];
        cout << laps << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<int64> d(n), v(n);
    for (int i = 0; i < n; ++i) cin >> d[i] >> v[i];

    // Time for one lap of student i = d[i] / v[i] hours.
    // We need the smallest T > 0 such that T / (d[i]/v[i]) is an integer for all i.
    // Let x_i = d[i] / gcd(d[i], v[i]), y_i = v[i] / gcd(d[i], v[i]).
    // Then lap time = x_i / y_i in lowest terms.
    //
    // If T = P / Q in lowest terms and T / (x_i / y_i) is integer,
    // then T must be a common multiple of these rationals.
    // The least such positive T is:
    //   L = lcm(x_i) / gcd(y_i)
    // and laps of student i at that time are:
    //   L / (x_i / y_i) = (lcm(x_i) / x_i) * (y_i / gcd(y_i))
    //
    // To avoid overflow, use __int128 for intermediate computations.

    vector<int64> x(n), y(n);
    for (int i = 0; i < n; ++i) {
        int64 g = std::gcd(d[i], v[i]);
        x[i] = d[i] / g;
        y[i] = v[i] / g;
    }

    i128 l = 1; // lcm of x_i
    for (int i = 0; i < n; ++i) {
        int64 g = std::gcd((int64)l, x[i]);
        l = l / g * x[i];
    }

    int64 gAll = y[0]; // gcd of y_i
    for (int i = 1; i < n; ++i) gAll = std::gcd(gAll, y[i]);

    for (int i = 0; i < n; ++i) {
        i128 ans = (l / x[i]) * (y[i] / gAll);
        long long out = (long long)ans; // guaranteed <= 2^31 - 1
        cout << out << '\n';
    }

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;

        while ((line = br.readLine()) != null && !line.trim().isEmpty()) {
            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());

            long[] distances = new long[n];
            long[] speeds = new long[n];

            for (int i = 0; i < n; i++) {
                distances[i] = Long.parseLong(st.nextToken());
                speeds[i] = Long.parseLong(st.nextToken());
            }

            // Time to complete one lap = distance / speed
            // We need time T such that T * speed_i / distance_i is integer for all i
            // T must be a common multiple of (distance_i / speed_i) in rational sense
            // T = LCM of (distance_i / speed_i) expressed as fractions
            // Better approach: T = LCM of (distance_i * k) / speed_i? 
            // Actually each student's lap time = d_i / v_i hours
            // We need T such that T / (d_i / v_i) = T * v_i / d_i is integer
            // So T must be a multiple of d_i / gcd(d_i, v_i)? No...
            // Let's think: T * v_i / d_i = integer => T * v_i is divisible by d_i
            // So T must be such that for all i: d_i | T * v_i
            // Let g_i = gcd(d_i, v_i). Then condition: (d_i/g_i) | T * (v_i/g_i)
            // Since (d_i/g_i) and (v_i/g_i) are coprime, (d_i/g_i) must divide T
            // So T must be a common multiple of all d_i/g_i
            // Minimal T = LCM of all (d_i / gcd(d_i, v_i))

            long lcm = 1;
            for (int i = 0; i < n; i++) {
                long g = gcd(distances[i], speeds[i]);
                long reducedDist = distances[i] / g;
                lcm = lcm(lcm, reducedDist);
            }

            // Now compute laps for each student: laps_i = T * v_i / d_i
            for (int i = 0; i < n; i++) {
                long laps = lcm * speeds[i] / distances[i];
                if (i > 0) System.out.print(" ");
                System.out.print(laps);
            }
            System.out.println();
        }
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }
}

import java.util.*;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            long[] d = new long[n];
            long[] v = new long[n];
            for (int i = 0; i < n; i++) {
                d[i] = sc.nextLong();
                v[i] = sc.nextLong();
            }

            // LCM of all d[i]
            BigInteger lcmD = BigInteger.valueOf(d[0]);
            for (int i = 1; i < n; i++) {
                BigInteger bi = BigInteger.valueOf(d[i]);
                lcmD = lcmD.divide(lcmD.gcd(bi)).multiply(bi);
            }

            // GCD of all v[i]
            BigInteger gcdV = BigInteger.valueOf(v[0]);
            for (int i = 1; i < n; i++) {
                gcdV = gcdV.gcd(BigInteger.valueOf(v[i]));
            }

            // laps[i] = (lcmD / d[i]) * (v[i] / gcdV)
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                BigInteger laps = lcmD.divide(BigInteger.valueOf(d[i]))
                                      .multiply(BigInteger.valueOf(v[i]).divide(gcdV));
                if (i > 0) sb.append(" ");
                sb.append(laps.toString());
            }
            System.out.println(sb.toString());
        }
    }
}

import java.io.*;
import java.util.*;
import java.math.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static BigInteger gcd(BigInteger a, BigInteger b) {
        return a.gcd(b);
    }

    static BigInteger lcm(BigInteger a, BigInteger b) {
        return a.divide(a.gcd(b)).multiply(b);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);

        BigInteger[] d = new BigInteger[n];
        BigInteger[] v = new BigInteger[n];
        BigInteger[] p = new BigInteger[n];
        BigInteger[] q = new BigInteger[n];

        BigInteger commonLcm = BigInteger.ONE;

        for (int i = 0; i < n; i++) {
            d[i] = new BigInteger(fs.next());
            v[i] = new BigInteger(fs.next());

            BigInteger g = gcd(d[i], v[i]);
            p[i] = d[i].divide(g); // reduced lap time numerator
            q[i] = v[i].divide(g); // reduced lap time denominator

            commonLcm = lcm(commonLcm, p[i]);
        }

        BigInteger[] ans = new BigInteger[n];
        for (int i = 0; i < n; i++) {
            // T = commonLcm hours, laps = T / (d/v) = commonLcm * v / d
            ans[i] = commonLcm.multiply(q[i]).divide(p[i]);
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(ans[i]);
            if (i + 1 < n) sb.append('\n');
        }
        System.out.print(sb.toString());
    }
}
